steps.script:
# Same position as exam mv07: the charger a 65 px line at y 650, the target a
# wide 140 px line at y 1120 (10.2" edge to edge), everyone else parked.
var st = GameState.state
var g = st.units.U_CUSTODIAN_GUARD_B
var k = 0
for m in g.models:
	m.position = {"x": 890.0 + float(k) * 65.0, "y": 650.0}
	k += 1
if g.has("flags"):
	g.flags.erase("last_shot_idx")
	g.flags.erase("shot_recently")
var t = st.units.U_CUSTODIAN_GUARD_C_P2
var j = 0
for m in t.models:
	m.position = {"x": 1160.0 + float(j) * 140.0, "y": 1120.0}
	j += 1
for uid in st.units:
	if uid == "U_CUSTODIAN_GUARD_B" or uid == "U_CUSTODIAN_GUARD_C_P2":
		continue
	var u = st.units[uid]
	var q = 0
	for m in u.get("models", []):
		if m.get("position") == null:
			continue
		if int(u.get("owner", 0)) == 1:
			m.position = {"x": 600.0 + 40.0 * float(q % 5), "y": 300.0}
		else:
			m.position = {"x": 1500.0 + 40.0 * float(q % 6), "y": 2300.0 - 40.0 * float(q / 6)}
		q += 1
return true

# FIX_MOVE_FOR_CHARGE ships OFF: load the opt-in profile AFTER configure()
# (configure wipes profiles).
var f = FileAccess.open("res://tests/bench_profiles/move_for_charge_on.json", FileAccess.READ)
var prof = JSON.parse_string(f.get_as_text())
f.close()
AIDecisionMaker.load_player_profile(1, prof)
return prof.parameters.size()

# Engine truth on the suggested move (Measurement, the charge's own measure):
# within 5" of the target's nearest model (a 5+), unengaged (09.05).
var d = AIPlayer.request_suggestion("U_CUSTODIAN_GUARD_B")
var dests = d.get("_ai_model_destinations", {})
var u = GameState.state.units.U_CUSTODIAN_GUARD_B
var gap = INF
var any_gap = INF
for m in u.models:
	var m2 = m.duplicate()
	if dests.has(m.id):
		m2["position"] = Vector2(float(dests[m.id][0]), float(dests[m.id][1]))
	for uid in GameState.state.units:
		var e_u = GameState.state.units[uid]
		if int(e_u.get("owner", 0)) != 2:
			continue
		for e in e_u.get("models", []):
			if not e.get("alive", true) or e.get("position") == null:
				continue
			var dd = Measurement.model_to_model_distance_inches(m2, e)
			any_gap = min(any_gap, dd)
			if uid == "U_CUSTODIAN_GUARD_C_P2":
				gap = min(gap, dd)
var notes = ""
for n in d.get("_ai_move_adjustments", []):
	notes += str(n) + " | "
var desc = str(d.get("_ai_description", ""))
return gap <= 5.02 and any_gap > 2.0 and notes.contains("this turn's charge needs a 5+") and desc.contains("staged for a 5+ charge")

# SHIPPED-DEFAULT CHECK: clearing the profile leaves FIX_MOVE_FOR_CHARGE at 0 —
# the centroid-aimed attack move (a 6+), no note, no 'staged for' suffix.
AIDecisionMaker.clear_player_profile(1)
var d = AIPlayer.request_suggestion("U_CUSTODIAN_GUARD_B")
var dests = d.get("_ai_model_destinations", {})
var u = GameState.state.units.U_CUSTODIAN_GUARD_B
var gap = INF
var any_gap = INF
for m in u.models:
	var m2 = m.duplicate()
	if dests.has(m.id):
		m2["position"] = Vector2(float(dests[m.id][0]), float(dests[m.id][1]))
	for uid in GameState.state.units:
		var e_u = GameState.state.units[uid]
		if int(e_u.get("owner", 0)) != 2:
			continue
		for e in e_u.get("models", []):
			if not e.get("alive", true) or e.get("position") == null:
				continue
			var dd = Measurement.model_to_model_distance_inches(m2, e)
			any_gap = min(any_gap, dd)
			if uid == "U_CUSTODIAN_GUARD_C_P2":
				gap = min(gap, dd)
var notes = ""
for n in d.get("_ai_move_adjustments", []):
	notes += str(n) + " | "
var desc = str(d.get("_ai_description", ""))
return gap >= 5.5 and gap <= 6.0 and not notes.contains("this turn's charge needs a") and desc.contains("moves to attack") and not desc.contains("staged for a")

# ...and reloading the profile restores the staged spot.
var f = FileAccess.open("res://tests/bench_profiles/move_for_charge_on.json", FileAccess.READ)
var prof = JSON.parse_string(f.get_as_text())
f.close()
AIDecisionMaker.load_player_profile(1, prof)
var d = AIPlayer.request_suggestion("U_CUSTODIAN_GUARD_B")
var dests = d.get("_ai_model_destinations", {})
var u = GameState.state.units.U_CUSTODIAN_GUARD_B
var gap = INF
var any_gap = INF
for m in u.models:
	var m2 = m.duplicate()
	if dests.has(m.id):
		m2["position"] = Vector2(float(dests[m.id][0]), float(dests[m.id][1]))
	for uid in GameState.state.units:
		var e_u = GameState.state.units[uid]
		if int(e_u.get("owner", 0)) != 2:
			continue
		for e in e_u.get("models", []):
			if not e.get("alive", true) or e.get("position") == null:
				continue
			var dd = Measurement.model_to_model_distance_inches(m2, e)
			any_gap = min(any_gap, dd)
			if uid == "U_CUSTODIAN_GUARD_C_P2":
				gap = min(gap, dd)
var notes = ""
for n in d.get("_ai_move_adjustments", []):
	notes += str(n) + " | "
var desc = str(d.get("_ai_description", ""))
return gap <= 5.02 and any_gap > 2.0

# The AI's own execution path: stage + confirm through AIPlayer, then ask
# the ENGINE where the models are (every model, per model).
var d = AIPlayer.request_suggestion("U_CUSTODIAN_GUARD_B")
NetworkIntegration.route_action({"type": "BEGIN_NORMAL_MOVE", "actor_unit_id": "U_CUSTODIAN_GUARD_B", "player": 1})
var ph = PhaseManager.current_phase_instance
if ph.has_method("has_pending_stratagem_window") and ph.has_pending_stratagem_window():
	var w = ph.get_pending_stratagem_window()
	NetworkIntegration.route_action({"type": "DECLINE_WINDOW_STRATAGEM", "player": int(w.get("player", 1)), "window_id": str(w.get("window_id", ""))})
AIPlayer._execute_ai_movement(1, d)
var u = GameState.state.units.U_CUSTODIAN_GUARD_B
var gap = INF
var any_gap = INF
for m in u.models:
	for uid in GameState.state.units:
		var e_u = GameState.state.units[uid]
		if int(e_u.get("owner", 0)) != 2:
			continue
		for e in e_u.get("models", []):
			if not e.get("alive", true) or e.get("position") == null:
				continue
			var dd = Measurement.model_to_model_distance_inches(m, e)
			any_gap = min(any_gap, dd)
			if uid == "U_CUSTODIAN_GUARD_C_P2":
				gap = min(gap, dd)
return bool(u.get("flags", {}).get("moved", false)) and not bool(u.get("flags", {}).get("advanced", false)) and gap <= 5.02 and any_gap > 2.0

# The charge is real: in the Charge phase the AI's own declaration for the
# squad prices the 5+ the staged move left (83%; the flag-off spot read 72%).
AIDecisionMaker.reset_caches()
var acts = PhaseManager.current_phase_instance.get_available_actions()
var dd = AIDecisionMaker.decide(9, GameState.create_snapshot(), acts, 1)
var tids = dd.get("payload", {}).get("target_unit_ids", [])
return str(dd.get("type", "")) == "DECLARE_CHARGE" and str(dd.get("actor_unit_id", "")) == "U_CUSTODIAN_GUARD_B" and "U_CUSTODIAN_GUARD_C_P2" in tids and str(dd.get("_ai_description", "")).contains("83% chance")
